/* AES-192: 13 round keys (12 rounds + initial). Key is 24 bytes. */
static void aes192_key_expand(const uint8_t *key, __m128i rk[13]) {
    /* Use byte array method for correctness, then load. 13*16 = 208 bytes, 52 words. */
    uint32_t w[52];
    memcpy(w, key, 24);
    /* words are little-endian host? AES key schedule treats key bytes as big-endian words.
       We'll do it on bytes to be safe. */
    uint8_t kb[24];
    memcpy(kb, key, 24);
    uint8_t out[13*16];
    /* standard expansion producing 52 32-bit words */
    uint32_t W[52];
    for (int i = 0; i < 6; i++) {
        W[i] = ((uint32_t)kb[4*i]<<24) | ((uint32_t)kb[4*i+1]<<16) | ((uint32_t)kb[4*i+2]<<8) | kb[4*i+3];
    }
