static void dump(const char *n, const uint8_t *b){ printf("%-20s ", n); for(int i=0;i<16;i++) printf("%02x", b[i]); printf("\n"); }

static void ghash_mul_ref(uint8_t *x, const uint8_t *h){
    uint8_t Z[16]={0}, V[16]; memcpy(V, h, 16);
    for(int i=0;i<128;i++){
        int byte=i/8, bit=7-(i%8);
        if((x[byte]>>bit)&1) for(int j=0;j<16;j++) Z[j]^=V[j];
        int lsb = V[15]&1; int carry=0;
        for(int j=0;j<16;j++){ int nc=V[j]&1; V[j]=(V[j]>>1)|(carry<<7); carry=nc; }
        if(lsb) V[0]^=0xe1;
    }
    memcpy(x, Z, 16);
}

/* schoolbook in polynomial (x^0 = LSB) domain to cross-check the reference */
static void poly_mul_256(const uint8_t *a, const uint8_t *b, uint8_t out[32]){
    memset(out, 0, 32);
    for(int i=0;i<128;i++){
        if(!((a[i/8]>>(i%8))&1)) continue;
        for(int j=0;j<128;j++){
            if((b[j/8]>>(j%8))&1){
                int p=i+j; out[p/8] ^= 1u<<(p%8);
            }
        }
    }
}
static void reduce_brute(uint8_t acc[16], const uint8_t hi[16]){
    for(int k=0;k<128;k++){
        if(!((hi[k/8]>>(k%8))&1)) continue;
        int offs[4]={0,1,2,7};
        for(int t=0;t<4;t++){
            int pos=k+offs[t];
            if(pos<128) acc[pos/8]^=1u<<(pos%8);
            else { int p=pos-128; for(int u=0;u<4;u++){ int q=p+offs[u]; acc[q/8]^=1u<<(q%8);} }
        }
    }
}

int main(){
    uint8_t H[16] = {0x66,0xe9,0x4b,0xd4,0xef,0x8a,0x2c,0x3b,0x88,0x4c,0xfa,0x59,0xca,0x34,0x2b,0x2e};
    uint8_t C[16] = {0x03,0x88,0xda,0xce,0x60,0xb6,0xa3,0x92,0xf3,0x28,0xc2,0xb9,0x71,0xb2,0xfe,0x78};
    uint8_t expect[16]; memcpy(expect, C, 16); ghash_mul_ref(expect, H);
    dump("ghash_mul_ref", expect);

    /* polynomial-domain multiply of bit-reversed inputs, reduce, bit-reverse back */
    __m128i Hr = full_reverse(_mm_loadu_si128((const __m128i*)H));
    __m128i Cr = full_reverse(_mm_loadu_si128((const __m128i*)C));
    uint8_t hb[16], cb[16];
    _mm_storeu_si128((__m128i*)hb, Hr); _mm_storeu_si128((__m128i*)cb, Cr);

    uint8_t prod[32]; poly_mul_256(hb, cb, prod);
    uint8_t acc[16]; memcpy(acc, prod, 16);
    reduce_brute(acc, prod+16);
    dump("poly reduced", acc);
    __m128i back = full_reverse(_mm_loadu_si128((const __m128i*)acc));
    uint8_t bb[16]; _mm_storeu_si128((__m128i*)bb, back);
    dump("back", bb);
    printf("match ref %d\n", memcmp(bb, expect, 16)==0);

    /* Now CLMUL product vs schoolbook product */
    __m128i p0 = _mm_clmulepi64_si128(Cr, Hr, 0x00);
    __m128i p1 = _mm_clmulepi64_si128(Cr, Hr, 0x11);
    __m128i p2 = _mm_clmulepi64_si128(Cr, Hr, 0x10);
    __m128i p3 = _mm_clmulepi64_si128(Cr, Hr, 0x01);
    __m128i mid = _mm_xor_si128(p2, p3);
    __m128i lo = _mm_xor_si128(p0, _mm_slli_si128(mid, 8));
    __m128i hi = _mm_xor_si128(p1, _mm_srli_si128(mid, 8));
    uint8_t lob[16], hib[16];
    _mm_storeu_si128((__m128i*)lob, lo); _mm_storeu_si128((__m128i*)hib, hi);
    printf("clmul==schoolbook lo %d hi %d\n", memcmp(lob, prod, 16)==0, memcmp(hib, prod+16, 16)==0);
    dump("school lo", prod); dump("clmul lo", lob);
    dump("school hi", prod+16); dump("clmul hi", hib);
    return 0;
}
