static inline __m128i clmul_reduce(__m128i a, __m128i b) {
    /* a, b in polynomial order (bit k = x^k), i.e. byte-swapped GHASH blocks */
    __m128i p0 = _mm_clmulepi64_si128(a, b, 0x00);
    __m128i p1 = _mm_clmulepi64_si128(a, b, 0x11);
    __m128i p2 = _mm_clmulepi64_si128(a, b, 0x10);
    __m128i p3 = _mm_clmulepi64_si128(a, b, 0x01);
    __m128i mid = _mm_xor_si128(p2, p3);
    __m128i lo = _mm_xor_si128(p0, _mm_slli_si128(mid, 8));
    __m128i hi = _mm_xor_si128(p1, _mm_srli_si128(mid, 8));
    /* reduce hi */
    #define SHL_CROSS(v, s) _mm_or_si128(_mm_slli_epi64(v, s), _mm_srli_epi64(_mm_slli_si128(v, 8), 64-(s)))
    __m128i ov = _mm_setzero_si128();
    int shifts[3] = {1,2,7};
    for (int i = 0; i < 3; i++) {
        int s = shifts[i];
        lo = _mm_xor_si128(lo, SHL_CROSS(hi, s));
        __m128i top = _mm_srli_si128(hi, 8);
        ov = _mm_xor_si128(ov, _mm_srli_epi64(top, 64 - s));
    }
    lo = _mm_xor_si128(lo, _mm_slli_epi64(ov, 1));
    lo = _mm_xor_si128(lo, _mm_slli_epi64(ov, 2));
    lo = _mm_xor_si128(lo, _mm_slli_epi64(ov, 7));
    return lo;
    #undef SHL_CROSS
}

static void ghash_mul_ref(uint8_t *x, const uint8_t *h){
    uint8_t Z[16]={0}, V[16]; memcpy(V, h, 16);
    for(int i=0;i<128;i++){
        int byte=i/8, bit=7-(i%8);
        if((x[byte]>>bit)&1) for(int j=0;j<16;j++) Z[j]^=V[j];
        int lsb = V[15]&1; int carry=0;
        for(int j=0;j<16;j++){ int nc=V[j]&1; V[j]=(V[j]>>1)|(carry<<7); carry=nc; }
        if(lsb) V[0]^=0xe1;
    }
    memcpy(x, Z, 16);
}

int main(){
    uint8_t H[16] = {0x66,0xe9,0x4b,0xd4,0xef,0x8a,0x2c,0x3b,0x88,0x4c,0xfa,0x59,0xca,0x34,0x2b,0x2e};
    uint8_t C[16] = {0x03,0x88,0xda,0xce,0x60,0xb6,0xa3,0x92,0xf3,0x28,0xc2,0xb9,0x71,0xb2,0xfe,0x78};
    uint8_t expect[16]; memcpy(expect, C, 16); ghash_mul_ref(expect, H);
    dump("expect", expect);

    __m128i Hp = bswap128(_mm_loadu_si128((const __m128i*)H));
    __m128i Cp = bswap128(_mm_loadu_si128((const __m128i*)C));
    __m128i Rp = clmul_reduce(Cp, Hp);
    __m128i R = bswap128(Rp);
    uint8_t rb[16]; _mm_storeu_si128((__m128i*)rb, R);
    dump("got   ", rb);
    printf("match %d\n", memcmp(rb, expect, 16)==0);

    /* full GHASH of the NIST case: S = (C*H ^ L) * H */
    uint8_t L[16]={0}; L[15]=0x80; /* 128 bits */
    uint8_t mid[16]; memcpy(mid, expect, 16);
    for(int i=0;i<16;i++) mid[i]^=L[i];
    uint8_t S[16]; memcpy(S, mid, 16); ghash_mul_ref(S, H);
    dump("S expect", S);

    __m128i Lp = bswap128(_mm_loadu_si128((const __m128i*)L));
    __m128i Sp = clmul_reduce(_mm_xor_si128(Rp, Lp), Hp);
    uint8_t sb[16]; _mm_storeu_si128((__m128i*)sb, bswap128(Sp));
    dump("S got   ", sb);
    printf("S match %d\n", memcmp(sb, S, 16)==0);
    return 0;
}
