void aes_key_expand(const uint8_t *key, int keylen, __m128i *rk, int *Nr_out) {
    int Nk = keylen/4;
    int Nr = (keylen==16)?10:(keylen==24)?12:14;
    *Nr_out = Nr;
    int total = 4*(Nr+1);
    uint32_t W[60];
    for (int i = 0; i < Nk; i++)
        W[i] = ((uint32_t)key[4*i]<<24)|((uint32_t)key[4*i+1]<<16)|((uint32_t)key[4*i+2]<<8)|key[4*i+3];
    static const uint32_t RCON[11] = {0,0x01,0x02,0x04,0x08,0x10,0x20,0x40,0x80,0x1b,0x36};
    for (int i = Nk; i < total; i++) {
        uint32_t temp = W[i-1];
        if (i % Nk == 0) temp = subword((temp<<8)|(temp>>24)) ^ (RCON[i/Nk]<<24);
        else if (Nk > 6 && i % Nk == 4) temp = subword(temp);
        W[i] = W[i-Nk] ^ temp;
    }
    for (int i = 0; i < Nr+1; i++) {
        uint8_t b[16];
        for (int j = 0; j < 4; j++) {
            uint32_t w = W[4*i+j];
            b[4*j]=w>>24; b[4*j+1]=w>>16; b[4*j+2]=w>>8; b[4*j+3]=w;
        }
        rk[i] = _mm_loadu_si128((const __m128i*)b);
    }
