    m = _mm_set1_epi8(0x33);
    r = _mm_or_si128(_mm_slli_epi16(_mm_and_si128(r, m), 2), _mm_srli_epi16(_mm_and_si128(r, _mm_set1_epi8(0xcc)), 2));
    m = _mm_set1_epi8(0x0f);
    r = _mm_or_si128(_mm_slli_epi16(_mm_and_si128(r, m), 4), _mm_srli_epi16(_mm_and_si128(r, _mm_set1_epi8(0xf0)), 4));
