    __m128i l0 = gmul_noreduce_lo(b0, pw[4], &h0);
    __m128i l1 = gmul_noreduce_lo(b1, pw[3], &h1);
    __m128i l2 = gmul_noreduce_lo(b2, pw[2], &h2);
    __m128i l3 = gmul_noreduce_lo(b3, pw[1], &h3);
    return reduce_hi(_mm_xor_si128(_mm_xor_si128(l0,l1),_mm_xor_si128(l2,l3)), _mm_xor_si128(_mm_xor_si128(h0,h1),_mm_xor_si128(h2,h3)));
}
int main(){
    __m128i H = reflect_bytes(_mm_set_epi64x(0x123456789abcdef0ULL, 0x0fedcba987654321ULL));
    __m128i pw[5]; pw[1]=H; pw[2]=gmul(H,H); pw[3]=gmul(pw[2],H); pw[4]=gmul(pw[2],pw[2]);
    __m128i r[8];
    for (int i = 0; i < 8; i++) r[i] = _mm_set_epi64x(0x1111111111111111ULL*i, 0x2222222222222222ULL+i);
    __m128i state = _mm_set_epi64x(0xaaa, 0xbbb);
    __m128i seq = state;
    for (int i = 0; i < 8; i++) seq = gmul(_mm_xor_si128(seq, r[i]), H);
    __m128i acc = ghash4(_mm_xor_si128(state, r[0]), r[1], r[2], r[3], pw);
    __m128i st2 = ghash4(acc, r[4], r[5], r[6], pw);
    st2 = gmul(_mm_xor_si128(st2, r[7]), H);
    uint8_t a[16], b[16];
    _mm_storeu_si128((__m128i*)a, seq); _mm_storeu_si128((__m128i*)b, st2);
    printf("8-block combine %s\n", memcmp(a,b,16)==0?"OK":"FAIL");
    /* try alternative: second group should be (acc XOR r4) */
    __m128i st3 = ghash4(_mm_xor_si128(acc, r[4]), r[5], r[6], r[7], pw);
    _mm_storeu_si128((__m128i*)b, st3);
    printf("alt combine %s\n", memcmp(a,b,16)==0?"OK":"FAIL");
