#include <stdint.h>
#include <string.h>
#include <openssl/evp.h>

/* out must hold pt_len + 16 bytes; returns ciphertext || tag */
int evp_gcm_encrypt(const uint8_t *key, int keylen,
                    const uint8_t *nonce, int noncelen,
                    const uint8_t *aad, size_t aad_len,
                    const uint8_t *pt, size_t pt_len,
                    uint8_t *out) {
    const EVP_CIPHER *cipher = NULL;
    if (keylen == 16) cipher = EVP_aes_128_gcm();
    else if (keylen == 24) cipher = EVP_aes_192_gcm();
    else if (keylen == 32) cipher = EVP_aes_256_gcm();
    else return -1;

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;
    int ok = 1, len = 0, total = 0;
    ok &= EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL) == 1;
    ok &= EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, noncelen, NULL) == 1;
    ok &= EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce) == 1;
    if (aad && aad_len) {
        int alen = 0;
        ok &= EVP_EncryptUpdate(ctx, NULL, &alen, aad, (int)aad_len) == 1;
    }
    /* encrypt in large chunks to keep the loop tight */
    size_t off = 0;
    while (off < pt_len) {
        size_t chunk = pt_len - off;
        if (chunk > (1<<30)) chunk = 1<<30;
        ok &= EVP_EncryptUpdate(ctx, out + off, &len, pt + off, (int)chunk) == 1;
        off += len;
    }
    int fin = 0;
    ok &= EVP_EncryptFinal_ex(ctx, out + off, &fin) == 1;
    off += fin;
    uint8_t tag[16];
    ok &= EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag) == 1;
    memcpy(out + off, tag, 16);
    EVP_CIPHER_CTX_free(ctx);
    return ok ? (int)(off + 16) : -1;
}
EOF
